head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf10101";
scwin.proft_partc_acc_yn = null;
scwin.chk_cash_pay_yn = null;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — divReckDdTpCdList

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.proft_partc_acc_yn = $c.util.getComponent('proft_partc_acc_yn');
        scwin.chk_cash_pay_yn = $c.util.getComponent('chk_cash_pay_yn');
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_conds();
        scwin.init_datefmt_cal_exerStrtDd();
        scwin.init_datefmt_cal_exerEndDd();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf10101.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "rd_divReckDdTpCd", fn: function(){ return (!(String(((dma_pageContext.get("divReckDdTpCdList") ?? "")) === null ? '' : ((dma_pageContext.get("divReckDdTpCdList") ?? ""))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        const ok = !!b.fn();
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_objIsuCd", fn: function () { return String((dma_pageContext.get("objIsuCd") ?? "")); } },
        { childId: "ipt_objIsuNm", fn: function () { return String((dma_pageContext.get("objIsuNm") ?? "")); } },
        { childId: "ipt_stkRelCorpbndExerPrc", fn: function () { return String((dma_pageContext.get("stkRelCorpbndExerPrc") ?? "")); } },
        { childId: "ipt_exerRto", fn: function () { return String((dma_pageContext.get("exerRto") ?? "")); } },
        { childId: "cal_exerStrtDd", fn: function () { return String((dma_pageContext.get("exerStrtDd") ?? "")); } },
        { childId: "cal_exerEndDd", fn: function () { return String((dma_pageContext.get("exerEndDd") ?? "")); } },
        { childId: "ipt_clmInstNm", fn: function () { return String((dma_pageContext.get("clmInstNm") ?? "")); } },
        { childId: "ipt_clmInstCd", fn: function () { return String((dma_pageContext.get("clmInstCd") ?? "")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_datefmt_cal_exerStrtDd
 * @description 초기화 — datefmt cal exer Strt Dd
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_exerStrtDd = function () { $c.date.checkCalendarFormat("cal_exerStrtDd", "yyyyMMdd"); };

/**
 * @method
 * @name init_datefmt_cal_exerEndDd
 * @description 초기화 — datefmt cal exer End Dd
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_exerEndDd = function () { $c.date.checkCalendarFormat("cal_exerEndDd", "yyyyMMdd"); };

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.chng_stk_rel_corpbnd_rght_tp_cd('' + dma_pageContext.get("stk_rel_corpbnd_rght_tp_cd") + '');
        $("input[name='stkRelCorpbndExerPrc']").trigger('onkeyup');

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf10101.onpageload' }); }
};

// [A] 초기 목록 미해결 — jldinf10101: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name slc_stkRelCorpbndRghtTpCd_onchange
 * @description slc_stkRelCorpbndRghtTpCd 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_stkRelCorpbndRghtTpCd_onchange = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.chng_stk_rel_corpbnd_rght_tp_cd(selfVar.value);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf10101.slc_stkRelCorpbndRghtTpCd_onchange' }); }
};

/**
 * @method
