 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_openSelectInstCd_onclick = function(e){
    try {
        scwin.open_select_inst_cd()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf10101.btn_openSelectInstCd_onclick' }); }
