///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name compEnable
 * @description 표준 API 조합으로 새로 작성한 검사 함수
 * @param {*} id id
 * @param {*} enable enable
 * @returns {void}
 * @hidden N
 */
scwin.compEnable = function (id, enable) { try { const c = $c.util.getComponent(String(id)); if (c && c.setDisabled) { c.setDisabled(!enable); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'authored-fn' }); return; } };

/**
 * @method
 * @name open_objStkStdCd
 * @description open obj Stk Std Cd 처리
 * @param {*} item_id item_id
 * @param {*} item_nm item_nm
 * @returns {void}
 * @hidden N
 */
scwin.open_objStkStdCd = function (item_id, item_nm) {
    const gubun = $c.util.getComponent('slc_stkRelCorpbndRghtTpCd').getValue();
    if (gubun === "10" || gubun === "11" || gubun === "21" || gubun === "22") {
        $c.util.getComponent('ipt_isurCd').setValue($c.util.getComponent('ipt_isurCd').getValue());
    } else {
        $c.util.getComponent('ipt_isurCd').setValue("");
    }
    formName = (document.JLDINF10101 || { elements: [] });
    fn_objStkStdCd(formName, item_id, item_nm, "STD1");
};

/**
 * @method
 * @name sendForm
 * @description send Form 처리
 * @param {*} fm fm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.sendForm = async function (fm) {
    fm = (document.JLDINF10101 || { elements: [] });
    let chk_cash_pay_yn = "N";
    let chk_sb_pay_yn = "N";
    if (($c.util.getComponent('slc_stkRelCorpbndRghtTpCd').getValue() === null ? '' : String($c.util.getComponent('slc_stkRelCorpbndRghtTpCd').getValue())) === '') {
        await $c.win.alert("권리구분을 선택하세요.");
        document.stk_rel_corpbnd_rght_tp_cd.focus();
        return;
    }
    if ($c.util.getComponent('slc_stkRelCorpbndRghtTpCd').getValue() !== "40") {
        if (($c.util.getComponent('ipt_objIsuCd').getValue() === null ? '' : String($c.util.getComponent('ipt_objIsuCd').getValue())) === '') {
            await $c.win.alert("대상증권코드를  입력하세요.");
            $c.util.getComponent('ipt_objIsuNm').setValue("");
            $c.util.getComponent("ipt_objIsuNm").focus();
            return;
        }
        if (($c.util.getComponent('ipt_stkRelCorpbndExerPrc').getValue() === null ? '' : String($c.util.getComponent('ipt_stkRelCorpbndExerPrc').getValue())) === '') {
            await $c.win.alert("행사가격을 입력하세요.");
            $c.util.getComponent("ipt_stkRelCorpbndExerPrc").focus();
            return;
        }
        if (($c.util.getComponent('ipt_exerRto').getValue() === null ? '' : String($c.util.getComponent('ipt_exerRto').getValue())) === '') {
            await $c.win.alert("행사비율을 입력하세요.");
            $c.util.getComponent("ipt_exerRto").focus();
            return;
        }
        if (($c.util.getComponent('cal_exerStrtDd').getValue() === null ? '' : String($c.util.getComponent('cal_exerStrtDd').getValue())) === '') {
            await $c.win.alert("행사개시일을 입력하세요.");
            $c.util.getComponent("cal_exerStrtDd").focus();
            return;
        }
        if (($c.util.getComponent('cal_exerEndDd').getValue() === null ? '' : String($c.util.getComponent('cal_exerEndDd').getValue())) === '') {
            await $c.win.alert("행사종료일을 입력하세요.");
            $c.util.getComponent("cal_exerEndDd").focus();
            return;
        }
