            chk_cash_pay_yn = "Y";
        }
        if ((String($c.util.getComponent('chk_sb_pay_yn').getValue() || "") !== "")) {
            chk_sb_pay_yn = "Y";
        }
        if (($c.util.getComponent('ipt_clmInstCd').getValue() === null ? '' : String($c.util.getComponent('ipt_clmInstCd').getValue())) === '') {

        }
    }
    if ($c.util.getComponent('slc_stkRelCorpbndRghtTpCd').getValue() === "40" && ($("td#proft_partc_acc_yn input:checked").val() === "" || $("td#proft_partc_acc_yn input:checked").val() === null)) {
        await $c.win.alert("누적여부를 선택하세요.");
        scwin.proft_partc_acc_yn.focus();
