 * @name chng_stk_rel_corpbnd_rght_tp_cd
 * @description chng stk rel corpbnd rght tp cd 처리
 * @param {*} val val
 * @returns {void}
 * @hidden N
 */
scwin.chng_stk_rel_corpbnd_rght_tp_cd = function (val) {
    if (val === "40") {
        scwin.compEnable("proft_partc_acc_ynY", true);
        scwin.compEnable("proft_partc_acc_ynN", true);
    } else {
        scwin.compEnable("proft_partc_acc_ynY", false, false);
        scwin.compEnable("proft_partc_acc_ynN", false, false);
        $('input[name=proft_partc_acc_yn]').attr("checked", false);
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @param {*} gubun gubun
 * @returns {void}
 * @hidden N
 */
scwin.delete = function (gubun) {
    if (gubun === "1") {
        $c.util.getComponent('ipt_objIsuCd').setValue("");
        $c.util.getComponent('ipt_objIsuNm').setValue("");
    } else {
        if (gubun === "2") {
            $c.util.getComponent('ipt_clmInstCd').setValue("");
            $c.util.getComponent('ipt_clmInstNm').setValue("");
        }
    }
};

